// The site as hello describes it (CLAUDE.md invariant 7): route, zones, loop length and vehicles.
// Nothing here knows this particular mine. A route that doesn't add up is reported in `issues`
// rather than silently trusted; a hello with no usable route is refused.
import type { Hello, RouteSegment } from './protocol.ts';

const EPS_M = 0.01;

export interface Range {
  startM: number;
  lengthM: number; // startM + lengthM may pass the loop end, meaning the range wraps
}

export interface Segment {
  segmentId: string;
  zoneId: string;
  kind: string;
  startM: number;
  lengthM: number;
}

export interface Zone {
  zoneId: string;
  ranges: Range[];
  lengthM: number;
  segmentIds: string[];
  kinds: string[];
}

export interface Site {
  readonly siteId: string;
  readonly loopLengthM: number;
  readonly segments: readonly Segment[];
  readonly zones: readonly Zone[]; // in the order they first appear along the route
  readonly vehicles: readonly string[];
  segment(segmentId: string): Segment | undefined;
  zone(zoneId: string): Zone | undefined;
  toLoop(segmentId: string, offsetM: number): number | undefined;
  zoneAt(positionM: number): Zone | undefined;
  bayZones(): Zone[];
}

export class SiteError extends Error {}

export function buildSite(hello: Hello): { site: Site; issues: string[] } {
  const loop = hello.loop_length_m;
  if (!Array.isArray(hello.route) || hello.route.length === 0) throw new SiteError('hello has no route');
  if (!(loop > 0)) throw new SiteError(`hello has no usable loop length (${loop})`);

  const issues: string[] = [];
  const segments = [...hello.route].sort((a, b) => a.start_m - b.start_m).map(toSegment);

  const seen = new Set<string>();
  for (const s of segments) {
    if (seen.has(s.segmentId)) issues.push(`duplicate segment id ${s.segmentId}`);
    seen.add(s.segmentId);
  }
  for (let i = 1; i < segments.length; i++) {
    const prev = segments[i - 1]!, cur = segments[i]!;
    const prevEnd = prev.startM + prev.lengthM;
    if (cur.startM > prevEnd + EPS_M) issues.push(`gap of ${round(cur.startM - prevEnd)} m between ${prev.segmentId} and ${cur.segmentId}`);
    if (cur.startM < prevEnd - EPS_M) issues.push(`${prev.segmentId} and ${cur.segmentId} overlap by ${round(prevEnd - cur.startM)} m`);
  }
  const covered = segments.reduce((sum, s) => sum + s.lengthM, 0);
  if (Math.abs(covered - loop) > EPS_M) issues.push(`route covers ${round(covered)} m of a ${round(loop)} m loop`);

  const zones = buildZones(segments, loop);
  for (const z of zones) {
    if (z.ranges.length > 1) issues.push(`zone ${z.zoneId} is in ${z.ranges.length} separate stretches`);
  }

  const bySegment = new Map(segments.map((s) => [s.segmentId, s]));
  const byZone = new Map(zones.map((z) => [z.zoneId, z]));
  const norm = (p: number) => ((p % loop) + loop) % loop;

  const site: Site = {
    siteId: hello.site_id,
    loopLengthM: loop,
    segments,
    zones,
    vehicles: [...hello.vehicles],
    segment: (id) => bySegment.get(id),
    zone: (id) => byZone.get(id),
    toLoop(segmentId, offsetM) {
      const s = bySegment.get(segmentId);
      return s && Number.isFinite(offsetM) ? s.startM + offsetM : undefined;
    },
    zoneAt(positionM) {
      if (!Number.isFinite(positionM)) return undefined;
      const p = norm(positionM);
      const s = segments.find((x) => p >= x.startM - EPS_M / 2 && p < x.startM + x.lengthM);
      return s && byZone.get(s.zoneId);
    },
    bayZones: () => zones.filter((z) => z.kinds.includes('bay')),
  };
  return { site, issues };
}

function toSegment(r: RouteSegment): Segment {
  return { segmentId: r.segment_id, zoneId: r.zone_id, kind: r.kind, startM: r.start_m, lengthM: r.length_m };
}

// Consecutive segments of one zone make a range; a zone at both ends of the route is one range
// across the wrap.
function buildZones(segments: Segment[], loop: number): Zone[] {
  const runs: Array<{ zoneId: string; range: Range }> = [];
  for (const s of segments) {
    const last = runs.at(-1);
    if (last && last.zoneId === s.zoneId && Math.abs(last.range.startM + last.range.lengthM - s.startM) <= EPS_M) {
      last.range.lengthM += s.lengthM;
    } else {
      runs.push({ zoneId: s.zoneId, range: { startM: s.startM, lengthM: s.lengthM } });
    }
  }
  const first = runs[0], last = runs.at(-1);
  if (first && last && runs.length > 1 && first.zoneId === last.zoneId &&
      Math.abs(first.range.startM) <= EPS_M && Math.abs(last.range.startM + last.range.lengthM - loop) <= EPS_M) {
    last.range.lengthM += first.range.lengthM;
    runs.shift();
  }

  const order: string[] = [];
  for (const s of segments) if (!order.includes(s.zoneId)) order.push(s.zoneId);
  return order.map((zoneId) => {
    const mine = segments.filter((s) => s.zoneId === zoneId);
    const ranges = runs.filter((r) => r.zoneId === zoneId).map((r) => r.range).sort((a, b) => a.startM - b.startM);
    return {
      zoneId,
      ranges,
      lengthM: ranges.reduce((sum, r) => sum + r.lengthM, 0),
      segmentIds: mine.map((s) => s.segmentId),
      kinds: [...new Set(mine.map((s) => s.kind))],
    };
  });
}

const round = (x: number) => Math.round(x * 100) / 100;
// Every speed, delay and threshold the product relies on, with where it came from (CLAUDE.md
// invariant 7). Site geometry is not here: it comes from hello (site.ts). "measured" values are from
// the live gateway (research/README.md); "decided" values are ours, with the reason recorded.

export type Source = 'spec' | 'measured' | 'decided';

export interface Param {
  readonly value: number;
  readonly unit: 'm/s' | 'ms' | 'm' | '%';
  readonly source: Source;
  readonly ref: string;
}

const p = (value: number, unit: Param['unit'], source: Source, ref: string): Param => ({ value, unit, source, ref });

export const PARAMS = {
  // Speeds
  autoSpeedEmpty: p(3.0, 'm/s', 'spec', 'PROTOCOL.md §3, nominal speeds'),
  autoSpeedLoaded: p(2.0, 'm/s', 'spec', 'PROTOCOL.md §3, nominal speeds'),
  manualSpeedEmptyFull: p(4.0, 'm/s', 'spec', 'PROTOCOL.md §3, manual at full throttle'),
  manualSpeedLoadedFull: p(3.0, 'm/s', 'spec', 'PROTOCOL.md §3, manual at full throttle'),
  limpHomeSpeed: p(1.0, 'm/s', 'spec', 'PROTOCOL.md §6.6'),
  reverseSpeedEmpty: p(3.0, 'm/s', 'measured', 'research/README.md, probe S3: EXIT_ZONE reversed at 3.0 m/s'),
  reverseSpeedLoaded: p(2.0, 'm/s', 'spec', 'assumed from the autonomous loaded speed; not measured (CONTEXT.md assumption 6)'),

  // Work cycle
  loadTime: p(20_000, 'ms', 'spec', 'PROTOCOL.md §3, loads for about 20 s'),
  dumpTime: p(12_000, 'ms', 'spec', 'PROTOCOL.md §3, dumps for about 12 s'),
  chargeBelow: p(25, '%', 'spec', 'PROTOCOL.md §3, charges below 25 % at the end of the bay'),
  chargeTo: p(90, '%', 'spec', 'PROTOCOL.md §3, charges to 90 %'),

  // Commands and control
  supervisoryDelayMax: p(6_000, 'ms', 'spec', 'PROTOCOL.md §5, take effect 1 to 6 s after acceptance'),
  deadman: p(500, 'ms', 'spec', 'PROTOCOL.md §6.3; ~0.4 s measured in probe S4'),
  leaseIdleTimeout: p(10_000, 'ms', 'spec', 'PROTOCOL.md §6.4; 10.1 s measured in probe S4'),
  driveInterval: p(100, 'ms', 'spec', 'PROTOCOL.md §6.2, stream at 10 to 20 Hz'),
  exitZoneStopOutside: p(2, 'm', 'spec', 'PROTOCOL.md §5, stops about 2 m outside; 2.0 m measured in probe S3'),
  heartbeatInterval: p(2_000, 'ms', 'spec', 'PROTOCOL.md §4.3; 2.006 to 2.014 s measured'),

  // Data-confidence thresholds (TESTING.md "Thresholds"; owned by the ingest task)
  truckOldAfter: p(2_000, 'ms', 'decided', 'longest normal gap between one truck\'s messages was 1.67 s'),
  truckSilentAfter: p(5_000, 'ms', 'decided', 'flags only the known silent trucks in all three captures; leaves 5 s of the 10 s alarm budget'),
  frozenAfter: p(3_000, 'ms', 'decided', 'flags exactly the one frozen truck per capture, nothing else'),
  frozenMinReportedSpeed: p(0.5, 'm/s', 'decided', 'below this a truck may honestly be creeping'),
  frozenMaxMovement: p(0.05, 'm', 'decided', 'frozen positions repeat exactly; real motion at 0.5 m/s moves 1.5 m in 3 s'),
  linkDownAfter: p(5_000, 'ms', 'decided', '2.5 heartbeat intervals'),

  // Blast safety and operator attention
  cantClearAlarmWithin: p(10_000, 'ms', 'decided', 'CLAUDE.md invariant 5; TESTING.md L4.R1'),
  autoResumeWithin: p(15_000, 'ms', 'decided', 'TESTING.md L4.R3: command delay plus one retry, with margin'),
  estopAutoSendWithin: p(10_000, 'ms', 'decided', 'TESTING.md L7.8: a pending e-stop is sent on reconnect only within 10 s'),
  realertAfter: p(15 * 60_000, 'ms', 'decided', 'TESTING.md L2.63'),
  escalateAfter: p(30 * 60_000, 'ms', 'decided', 'TESTING.md L2.63'),
} as const satisfies Record<string, Param>;

export type ParamName = keyof typeof PARAMS;

// TESTING.md L1.1 and L1.3: rules about what product code may contain, checked over src/.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync, readdirSync } from 'node:fs';
import { join, relative } from 'node:path';

const SRC = new URL('../src/', import.meta.url).pathname;

function sourceFiles(dir: string): string[] {
  return readdirSync(dir, { withFileTypes: true }).flatMap((e) =>
    e.name.startsWith('._') ? [] : e.isDirectory() ? sourceFiles(join(dir, e.name)) : e.name.endsWith('.ts') ? [join(dir, e.name)] : [],
  );
}

// L1.1: only the clock adapter may touch the wall clock or timers.
const WALL_CLOCK = [
  /\bDate\.now\s*\(/,
  /\bnew\s+Date\s*\(/,
  /\bperformance\.now\s*\(/,
  /\bprocess\.hrtime\b/,
  /(?<![.\w])(setTimeout|setInterval|setImmediate|clearTimeout|clearInterval)\s*\(/,
];

// L1.3: this site's names and numbers. The product takes them from hello and zone_event instead.
const SITE_LITERALS = [
  /\b(DECLINE|L4_NORTH|DRAW_12|L4_SOUTH|INCLINE|TIP)\b/,
  /['"`]BAY['"`]/,
  /\bSEG-/,
  /\bHT-\d/,
  /\b1600(\.0)?\b/,
  /\b120_?000\b/,
];

function violations(text: string, rules: RegExp[]): string[] {
  return text.split('\n').flatMap((line, i) => rules.filter((r) => r.test(line)).map((r) => `line ${i + 1}: ${line.trim()}  [${r}]`));
}

test('L1.1 the rule catches each kind of wall-clock access', () => {
  for (const planted of ['const t = Date.now();', 'new Date()', 'performance.now()', 'process.hrtime.bigint()', 'setTimeout(f, 10)', 'clearInterval(h)']) {
    assert.equal(violations(planted, WALL_CLOCK).length, 1, planted);
  }
  assert.deepEqual(violations('clock.setTimeout(f, 10); clock.now()', WALL_CLOCK), []);
});

test('L1.1 no product module outside the clock adapter reads the wall clock', () => {
  const found = sourceFiles(SRC)
    .filter((f) => relative(SRC, f) !== 'clock.ts')
    .flatMap((f) => violations(readFileSync(f, 'utf8'), WALL_CLOCK).map((v) => `${relative(SRC, f)} ${v}`));
  assert.deepEqual(found, []);
});

test('L1.3 the rule catches each kind of site literal', () => {
  for (const planted of ["zone === 'DECLINE'", "if (z === 'BAY')", "'SEG-BAY'", "vehicle: 'HT-04'", 'const loop = 1600;', 'const notice = 120_000;']) {
    assert.equal(violations(planted, SITE_LITERALS).length, 1, planted);
  }
  assert.deepEqual(violations("segment.kind === 'bay'; const n = 16000;", SITE_LITERALS), []);
});

test('L1.3 product code contains none of this site\'s literals', () => {
  const found = sourceFiles(SRC).flatMap((f) => violations(readFileSync(f, 'utf8'), SITE_LITERALS).map((v) => `${relative(SRC, f)} ${v}`));
  assert.deepEqual(found, []);
});
// The site model is built from hello, never from constants (CLAUDE.md invariant 7). Tests use this
// site's real hello from the fixtures, and a deliberately different site.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { buildSite } from '../src/site.ts';
import type { Hello, RouteSegment } from '../src/protocol.ts';

function fixtureHello(): Hello {
  const lines = readFileSync(new URL('../research/fixtures/two-zones-closing.jsonl', import.meta.url), 'utf8').trim().split('\n');
  const rec = lines.map((l) => JSON.parse(l)).find((r) => r.kind === 'msg' && r.m.type === 'hello');
  return rec.m as Hello;
}

function hello(route: RouteSegment[], loop: number, vehicles = ['T1', 'T2']): Hello {
  return { type: 'hello', protocol: '3.0', site_id: 'X', server_time_ms: 0, vehicles, route, loop_length_m: loop, zones: [], leases: [] };
}

const seg = (segment_id: string, zone_id: string, start_m: number, length_m: number, kind = 'transit'): RouteSegment =>
  ({ segment_id, zone_id, start_m, length_m, kind });

test('this site: segments, zones in loop order, vehicles and loop length come from hello', () => {
  const { site, issues } = buildSite(fixtureHello());
  assert.deepEqual(issues, []);
  assert.equal(site.loopLengthM, 1600);
  assert.equal(site.segments.length, 9);
  assert.deepEqual(site.zones.map((z) => z.zoneId), ['BAY', 'DECLINE', 'L4_NORTH', 'DRAW_12', 'L4_SOUTH', 'INCLINE', 'TIP']);
  assert.equal(site.vehicles.length, 12);
  const decline = site.zone('DECLINE');
  assert.deepEqual(decline?.ranges, [{ startM: 80, lengthM: 500 }]);
});

test('this site: segment and offset map to loop position and back to a zone', () => {
  const { site } = buildSite(fixtureHello());
  assert.equal(site.toLoop('SEG-L4S-1', 112.4), 952.4);
  assert.equal(site.zoneAt(952.4)?.zoneId, 'L4_SOUTH');
  assert.equal(site.zoneAt(0)?.zoneId, 'BAY');
  assert.equal(site.zoneAt(1599.99)?.zoneId, 'TIP');
  assert.equal(site.zoneAt(1600)?.zoneId, 'BAY', 'wraps');
  assert.equal(site.zoneAt(-0.5)?.zoneId, 'TIP', 'wraps backwards');
  assert.equal(site.toLoop('SEG-NOPE', 1), undefined);
  assert.equal(site.toLoop('SEG-BAY', Number.NaN), undefined);
});

test('the bay is found by segment kind, not by name', () => {
  const { site } = buildSite(fixtureHello());
  assert.deepEqual(site.bayZones().map((z) => z.zoneId), ['BAY']);
  const other = buildSite(hello([seg('a', 'Depot', 0, 50, 'bay'), seg('b', 'Ramp', 50, 450)], 500)).site;
  assert.deepEqual(other.bayZones().map((z) => z.zoneId), ['Depot']);
});

test('a different site: other names, lengths, truck count, and a zone that wraps past the loop end', () => {
  const route = [
    seg('s1', 'North', 0, 100), seg('s2', 'Ramp', 100, 200), seg('s3', 'Face', 300, 200, 'load'),
    seg('s4', 'Shaft', 500, 350, 'dump'), seg('s5', 'North', 850, 50),
  ];
  const { site, issues } = buildSite(hello(route, 900, ['A', 'B', 'C', 'D', 'E', 'F', 'G']));
  assert.deepEqual(issues, []);
  assert.equal(site.vehicles.length, 7);
  assert.deepEqual(site.zones.map((z) => z.zoneId), ['North', 'Ramp', 'Face', 'Shaft']);
  assert.deepEqual(site.zone('North')?.ranges, [{ startM: 850, lengthM: 150 }], 'merged across the wrap');
  assert.equal(site.zoneAt(870)?.zoneId, 'North');
  assert.equal(site.zoneAt(20)?.zoneId, 'North');
  assert.equal(site.zoneAt(120)?.zoneId, 'Ramp');
  assert.equal(site.zone('North')?.lengthM, 150);
});

test('a zone in two separate stretches keeps both, and says so', () => {
  const route = [seg('a', 'P', 0, 100), seg('b', 'Q', 100, 100), seg('c', 'P', 200, 100), seg('d', 'R', 300, 100)];
  const { site, issues } = buildSite(hello(route, 400));
  assert.deepEqual(site.zone('P')?.ranges, [{ startM: 0, lengthM: 100 }, { startM: 200, lengthM: 100 }]);
  assert.equal(site.zoneAt(250)?.zoneId, 'P');
  assert.equal(issues.length, 1);
  assert.match(issues[0] ?? '', /P.*2 separate stretches/);
});

test('a malformed route is reported, not silently accepted', () => {
  const gap = buildSite(hello([seg('a', 'P', 0, 100), seg('b', 'Q', 120, 280)], 400)).issues;
  assert.ok(gap.some((i) => /gap/.test(i)), gap.join('; '));
  const overlap = buildSite(hello([seg('a', 'P', 0, 150), seg('b', 'Q', 100, 300)], 400)).issues;
  assert.ok(overlap.some((i) => /overlap/.test(i)), overlap.join('; '));
  const short = buildSite(hello([seg('a', 'P', 0, 100), seg('b', 'Q', 100, 200)], 400)).issues;
  assert.ok(short.some((i) => /300.*400|400.*300/.test(i)), short.join('; '));
  const dup = buildSite(hello([seg('a', 'P', 0, 200), seg('a', 'Q', 200, 200)], 400)).issues;
  assert.ok(dup.some((i) => /duplicate/.test(i)), dup.join('; '));
});

test('a hello with no usable route is refused outright', () => {
  assert.throws(() => buildSite(hello([], 400)), /no route/);
  assert.throws(() => buildSite(hello([seg('a', 'P', 0, 400)], 0)), /loop length/);
});
// Every parameter says where it came from (CLAUDE.md invariant 7).
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { PARAMS } from '../src/params.ts';

test('every parameter is a positive number with a source and a reference', () => {
  for (const [name, p] of Object.entries(PARAMS)) {
    assert.ok(Number.isFinite(p.value) && p.value > 0, `${name} value`);
    assert.ok(['spec', 'measured', 'decided'].includes(p.source), `${name} source`);
    assert.ok(p.ref.length > 10, `${name} needs a real reference`);
  }
});

test('values the research marks as assumed are not labelled measured', () => {
  assert.equal(PARAMS.reverseSpeedLoaded.source, 'spec');
  assert.match(PARAMS.reverseSpeedLoaded.ref, /not measured/);
});

test('the silent threshold leaves room inside the 10 s can\'t-clear budget', () => {
  assert.ok(PARAMS.truckSilentAfter.value < PARAMS.cantClearAlarmWithin.value);
  assert.ok(PARAMS.frozenAfter.value < PARAMS.cantClearAlarmWithin.value);
});
// TESTING.md L1: injectable time. The manual clock is what lets blast scenarios run in milliseconds.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { ManualClock } from '../src/clock.ts';

test('now() only moves when advanced', () => {
  const c = new ManualClock(1_000);
  assert.equal(c.now(), 1_000);
  c.advance(250);
  assert.equal(c.now(), 1_250);
});

test('timers fire in due order, and each sees now() equal to its due time', () => {
  const c = new ManualClock(0);
  const seen: Array<[string, number]> = [];
  c.setTimeout(() => seen.push(['b', c.now()]), 200);
  c.setTimeout(() => seen.push(['a', c.now()]), 100);
  c.setTimeout(() => seen.push(['c', c.now()]), 300);
  c.advance(250);
  assert.deepEqual(seen, [['a', 100], ['b', 200]]);
  assert.equal(c.now(), 250);
  c.advance(50);
  assert.deepEqual(seen.at(-1), ['c', 300]);
});

test('timers due at the same moment fire in the order they were set', () => {
  const c = new ManualClock(0);
  const seen: string[] = [];
  for (const k of ['x', 'y', 'z']) c.setTimeout(() => seen.push(k), 10);
  c.advance(10);
  assert.deepEqual(seen, ['x', 'y', 'z']);
});

test('a timer set by a firing timer runs within the same advance if it falls due', () => {
  const c = new ManualClock(0);
  const seen: number[] = [];
  const tick = () => { seen.push(c.now()); if (c.now() < 1_000) c.setTimeout(tick, 200); };
  c.setTimeout(tick, 200);
  c.advance(1_000);
  assert.deepEqual(seen, [200, 400, 600, 800, 1_000]);
});

test('a cleared timer never fires; clearing twice is harmless', () => {
  const c = new ManualClock(0);
  let fired = false;
  const h = c.setTimeout(() => { fired = true; }, 10);
  c.clearTimeout(h);
  c.clearTimeout(h);
  c.advance(100);
  assert.equal(fired, false);
  assert.equal(c.pending(), 0);
});

test('advance refuses to go backwards', () => {
  const c = new ManualClock(0);
  assert.throws(() => c.advance(-1), RangeError);
});

test('a runaway timer loop is stopped, not hung', () => {
  const c = new ManualClock(0);
  const again = () => { c.setTimeout(again, 0); };
  c.setTimeout(again, 0);
  assert.throws(() => c.advance(1), /runaway/);
});

// L1.2 at the clock level: a blast-length schedule of 12 trucks at 5 Hz (about 230 s of CLOSING and
// CLOSED) runs in well under 100 ms of real time. The full L1.2, with the blast engine, comes in task 5.
test('L1.2 (clock level) a blast-length timeline runs in under 100 ms', () => {
  const c = new ManualClock(0);
  let ticks = 0;
  for (let truck = 0; truck < 12; truck++) {
    const tick = () => { ticks++; c.setTimeout(tick, 200); };
    c.setTimeout(tick, 200);
  }
  const started = performance.now();
  c.advance(230_000);
  const took = performance.now() - started;
  assert.equal(ticks, 12 * 1_150);
  assert.ok(took < 100, `took ${took.toFixed(1)} ms`);
});

