import { readFileSync, readdirSync } from 'node:fs';
const dir = process.argv[2];
for (const f of readdirSync(dir).filter((x) => x.endsWith('.jsonl') && !x.startsWith('._'))) {
  const c = {};
  const vehicles = {};
  for (const l of readFileSync(dir + '/' + f, 'utf8').split('\n')) {
    if (!l) continue;
    const r = JSON.parse(l);
    let k = r.kind;
    if (k === 'msg') { k = 'msg:' + (r.m.type ?? '?'); if (r.m.type === 'telemetry') vehicles[r.m.vehicle_id] = (vehicles[r.m.vehicle_id] ?? 0) + 1; }
    c[k] = (c[k] ?? 0) + 1;
  }
  console.log(f, JSON.stringify(c), JSON.stringify(vehicles));
}

