// Compact timeline of a fixture: one line per record. Usage: node tl.mjs file [vehicle] [from] [to]
import { readFileSync } from 'node:fs';
const [file, veh, from = '0', to = '1e9'] = process.argv.slice(2);
const lines = readFileSync(file, 'utf8').split('\n').filter(Boolean).map((l) => JSON.parse(l));
let t0;
let i = 0;
for (const r of lines) {
  i++;
  if (r.kind === 'fixture') continue;
  t0 ??= r.rx_ms;
  const t = ((r.rx_ms - t0) / 1000).toFixed(2);
  if (+t < +from || +t > +to) continue;
  if (r.kind !== 'msg') { console.log(i, t, r.kind, JSON.stringify(r).slice(0, 200)); continue; }
  const m = r.m;
  if (m.type === 'telemetry') {
    if (veh && m.vehicle_id !== veh) continue;
    console.log(i, t, m.vehicle_id, 'seq', m.seq, 'skew', ((m.t_device_ms - r.rx_ms) / 1000).toFixed(2), m.state, m.task, 'v', m.speed_mps, m.direction, m.segment_id, m.offset_m, 'soc', m.soc_pct, 'pl', m.payload_kg, JSON.stringify(m.faults), m.control?.mode, m.control?.deadman);
  } else console.log(i, t, m.type, JSON.stringify(m).slice(0, 220));
}

