// Per vehicle: min/max of t_device_ms - rx_ms, and any field anomalies, across given files.
import { readFileSync } from 'node:fs';
for (const file of process.argv.slice(2)) {
  const per = {};
  for (const l of readFileSync(file, 'utf8').split('\n').filter(Boolean)) {
    const r = JSON.parse(l);
    if (r.kind !== 'msg' || r.m.type !== 'telemetry') continue;
    const m = r.m;
    const p = (per[m.vehicle_id] ??= { n: 0, min: Infinity, max: -Infinity, anomalies: new Set() });
    p.n++;
    const s = (m.t_device_ms - r.rx_ms) / 1000;
    p.min = Math.min(p.min, s); p.max = Math.max(p.max, s);
    if (typeof m.offset_m !== 'number') p.anomalies.add('offset:' + typeof m.offset_m);
    if (typeof m.speed_mps !== 'number') p.anomalies.add('speed:' + JSON.stringify(m.speed_mps));
    if (typeof m.soc_pct !== 'number') p.anomalies.add('soc:' + JSON.stringify(m.soc_pct));
    else if (m.soc_pct <= 1) p.anomalies.add('socfrac');
    if (typeof m.state !== 'string' || m.state !== m.state.toUpperCase()) p.anomalies.add('state:' + m.state);
    if (m.faults?.length) p.anomalies.add('faults:' + m.faults.join(','));
    if (m.task) p.anomalies.add('task:' + m.task);
  }
  console.log('==', file.split('/').pop());
  for (const [v, p] of Object.entries(per)) console.log(' ', v, p.n, 'skew', p.min.toFixed(2), p.max.toFixed(2), [...p.anomalies].join(' '));
}

