435	  #trackStill(t: Truck, pos: number, at: number): void {
436	    const speed = t.speed?.value;
437	    const moving = t.state !== undefined && MOVING_STATES.has(t.state.value) && speed !== undefined && speed >= PARAMS.frozenMinReportedSpeed.value;
